/**
 * Tab 3 — Thống kê đánh giá sự cố
 *
 * Charts:
 *  • Doughnut — Mức độ nghiêm trọng (bySeverity)
 *  • Doughnut — Tình trạng xảy ra (byOccurrenceStatus)
 *  • Bar      — Số sự cố theo tháng (trend)
 *  • H-Bar    — Hình thức báo cáo
 */
import React, { useCallback, useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { ChartEvent, ActiveElement } from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem, MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_VERTICAL,
  BAR_OPTIONS_HORIZONTAL,
  buildMonthListUrl,
  buildSeverityListUrl,
  buildReportTypeListUrl,
  buildBaseDateListUrl,
} from '../chartUtils';
import { ChartViewListPopover, ChartPopoverState } from './ChartViewListPopover';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
}

const toDoughnutData = (items: ChartDataItem[], colorOffset = 0) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: CHART_COLORS.slice(colorOffset, colorOffset + items.length),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

const ClickHint: React.FC = () => (
  <span
    title="Nhấn vào cột/phần để xem danh sách"
    style={{ marginLeft: 6, fontSize: '0.7rem', color: '#94a3b8', fontWeight: 400, cursor: 'default' }}
  >
    <i className="fas fa-hand-pointer" />
  </span>
);

export const Tab3Assessment: React.FC<Props> = ({ report, filters }) => {
  const [popover, setPopover] = useState<ChartPopoverState | null>(null);
  const closePopover = useCallback(() => setPopover(null), []);

  const makeClickHandler = (
    items: ChartDataItem[],
    urlBuilder:  (item: ChartDataItem) => string,
    hintBuilder: (item: ChartDataItem) => string,
  ) => (chartEvent: ChartEvent, elements: ActiveElement[]) => {
    if (!elements.length) { setPopover(null); return; }
    const idx  = elements[0].index;
    const item = items[idx];
    if (!item || item.count === 0) { setPopover(null); return; }
    const native = chartEvent.native as MouseEvent;
    setPopover({
      x:          native.clientX,
      y:          native.clientY,
      label:      item.label,
      filterHint: hintBuilder(item),
      listUrl:    urlBuilder(item),
    });
  };

  // Severity — use red/orange/green palette for impact readability
  const severityColors = ['#10b981', '#f59e0b', '#ef4444', '#94a3b8'];
  const severityDoughnut = {
    labels: report.bySeverity.map((d) => d.label),
    datasets: [
      {
        data: report.bySeverity.map((d) => d.count),
        backgroundColor: severityColors,
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
  };

  const severityOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.bySeverity,
      (item) => buildSeverityListUrl(item.key, filters),
      (item) => `Lọc mức độ: ${item.label} — ${item.count} sự cố`,
    ),
  };

  const occurrenceOptions = {
    ...DOUGHNUT_OPTIONS,
    onClick: makeClickHandler(
      report.byOccurrenceStatus,
      () => buildBaseDateListUrl(filters),
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  // Monthly trend bar
  const monthBarData = {
    labels: report.byMonth.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byMonth.map((d) => d.count),
        backgroundColor: report.byMonth.map((_, i) => {
          const cnt = report.byMonth[i].count;
          if (cnt === 0) return '#e2e8f0';
          const max = Math.max(...report.byMonth.map((x) => x.count), 1);
          const ratio = cnt / max;
          if (ratio > 0.66) return '#ef4444';
          if (ratio > 0.33) return '#f59e0b';
          return '#10b981';
        }),
        borderRadius: 4,
        borderSkipped: false,
      },
    ],
  };

  const monthOptions = {
    ...BAR_OPTIONS_VERTICAL,
    onClick: makeClickHandler(
      report.byMonth,
      (item) => buildMonthListUrl(item.key, filters),
      (item) => `Lọc theo tháng ${item.key} — ${item.count} sự cố`,
    ),
  };

  // Report type horizontal bar
  const reportTypeBar = {
    labels: report.byReportType.map((d) => d.label),
    datasets: [
      {
        label: 'Số sự cố',
        data: report.byReportType.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byReportType.length),
        borderRadius: 4,
      },
    ],
  };

  const reportTypeOptions = {
    ...BAR_OPTIONS_HORIZONTAL,
    onClick: makeClickHandler(
      report.byReportType,
      (item) => buildReportTypeListUrl(item.key, filters),
      (item) => `Lọc hình thức: ${item.label} — ${item.count} sự cố`,
    ),
  };

  return (
    <div>
      {popover && <ChartViewListPopover {...popover} onClose={closePopover} />}

      {/* Row 1: Severity + Occurrence doughnuts */}
      <div className={s.grid2} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-exclamation-triangle" /> Phân bố mức độ nghiêm trọng<ClickHint /></h3>
          <Doughnut data={severityDoughnut} options={severityOptions} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-check-circle" /> Phân bố tình trạng xảy ra<ClickHint /></h3>
          <Doughnut data={toDoughnutData(report.byOccurrenceStatus, 2)} options={occurrenceOptions} />
        </div>
      </div>

      {/* Row 2: Monthly trend bar */}
      <div className={s.chartCard} style={{ marginBottom: 16 }}>
        <h3>
          <i className="fas fa-chart-line" />
          Xu hướng sự cố theo tháng
          <span style={{ fontSize: '0.7rem', fontWeight: 400, marginLeft: 8, color: '#64748b' }}>
            Màu sắc phản ánh mức độ: xanh lá = thấp · vàng = trung bình · đỏ = cao
          </span>
          <ClickHint />
        </h3>
        <Bar data={monthBarData} options={monthOptions} />
      </div>

      {/* Row 3: Report type */}
      <div className={s.chartCard}>
        <h3><i className="fas fa-file-alt" /> Hình thức báo cáo<ClickHint /></h3>
        <Bar data={reportTypeBar} options={reportTypeOptions} />
      </div>
    </div>
  );
};
